import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    env_config = {k[len(env_prefix)+2:].replace('__', '.').lower(): v for k, v in env_mapping.items() if k.startswith(env_prefix + '__')}
    for key, value in env_config.items():
        parts = key.split('.')
        current = config
        for part in parts[:-1]:
            current = current.setdefault(part, {})
        current[parts[-1]] = _coerce(value, defaults.get(parts[-1]))
    return config

def _coerce(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ('true', '1', 'yes')
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'a': 1, 'b': 'two', 'c': True}
    assert load_config(defaults) == defaults

def test_toml():
    toml_content = b'a = 2\nb = "three"\nc = false'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    try:
        assert load_config({'a': 1, 'b': 'two', 'c': True}, 'config.toml') == {'a': 2, 'b': 'three', 'c': False}
    finally:
        os.remove('config.toml')

def test_env():
    env = {'APP__A': '3', 'APP__B': 'four', 'APP__C': 'true'}
    assert load_config({'a': 1, 'b': 'two', 'c': True}, env_prefix='APP', env_mapping=env) == {'a': 3, 'b': 'four', 'c': True}

def test_nested():
    env = {'APP__SERVER__PORT': '8080'}
    assert load_config({'server': {'port': 8000}}, env_prefix='APP', env_mapping=env) == {'server': {'port': 8080}}

def test_coercion():
    env = {'APP__A': '4', 'APP__B': '5.5', 'APP__C': 'yes'}
    assert load_config({'a': 1, 'b': 2.0, 'c': False}, env_prefix='APP', env_mapping=env) == {'a': 4, 'b': 5.5, 'c': True}

def test_error():
    env = {'APP__A': 'not_a_number'}
    with pytest.raises(ConfigError):
        load_config({'a': 1}, env_prefix='APP', env_mapping=env)

